import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, abort
import yaml
import hashlib
import hmac

app = Flask(__name__)

# Configuration loaded from environment
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
PROCESSOR_BIN = os.environ.get('PROCESSOR_BIN', '/opt/tools/imgprocess')
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'webp'}

def verify_webhook_signature(payload, signature):
    """Verify GitHub-style webhook signature"""
    secret = os.environ.get('WEBHOOK_SECRET', '')
    if not secret:
        return True  # Skip verification if no secret configured
    expected = 'sha256=' + hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def sanitize_filename(filename):
    """Basic filename sanitization - strips path separators"""
    return filename.replace('/', '').replace('\\', '').replace('..', '')

def get_image_metadata(filepath):
    """Extract metadata using external tool with user-controlled filename"""
    # Construct command to extract EXIF data
    cmd = f"{PROCESSOR_BIN} --extract-meta --input {filepath}"
    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            text=True
        )
        return result.stdout
    except subprocess.TimeoutExpired:
        return None

@app.route('/api/v2/images/upload', methods=['POST'])
def upload_image():
    """Handle image upload from authenticated users"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if not file.filename:
        return jsonify({'error': 'Empty filename'}), 400

    ext = file.filename.rsplit('.', 1)[-1].lower() if '.' in file.filename else ''
    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({'error': 'Invalid file type'}), 400

    safe_name = sanitize_filename(file.filename)
    filepath = os.path.join(UPLOAD_DIR, safe_name)
    file.save(filepath)

    return jsonify({'status': 'uploaded', 'filename': safe_name}), 201

@app.route('/api/v2/images/process', methods=['POST'])
def process_image():
    """Process an uploaded image - extracts metadata and generates thumbnail"""
    data = request.get_json()
    if not data or 'filename' not in data:
        return jsonify({'error': 'filename required'}), 400

    filename = data['filename']
    # Sanitize to prevent directory traversal
    filename = sanitize_filename(filename)
    filepath = os.path.join(UPLOAD_DIR, filename)

    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    # Extract metadata - VULNERABLE: filepath can contain shell metacharacters
    # because sanitize_filename only strips path separators, not shell chars
    metadata = get_image_metadata(filepath)

    if metadata is None:
        return jsonify({'error': 'Processing timeout'}), 504

    return jsonify({'metadata': metadata, 'status': 'processed'}), 200

@app.route('/api/v2/config/reload', methods=['POST'])
def reload_config():
    """Reload application config from YAML file"""
    config_path = os.environ.get('CONFIG_PATH', '/etc/app/config.yaml')
    try:
        with open(config_path, 'r') as f:
            config = yaml.safe_load(f)
        app.config.update(config)
        return jsonify({'status': 'reloaded'}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
